+const PAGE = 50
+
+export async function listInvoices(db: Db, q: ListQuery) {
+  const after = q.cursor ? decodeCursor(q.cursor) : Number.MAX_SAFE_INTEGER
+  const rows = await db.all("select * from invoices where id < ? order by id desc limit ?", after, PAGE + 1)
+  const page = rows.slice(0, PAGE)
+  const next = rows.length > PAGE ? encodeCursor(page[page.length - 1].id) : null
+  return { items: page, next }
+}

